function uniqueText(values:(string|null|undefined)[]){return Array.from(new Set(values.map(value=>value?.trim()).filter((value):value is string=>Boolean(value))))}
function compactValue(value:any){if(typeof value==="string")return value;if(value?.query)return value.query;if(value?.text)return value.text;if(value?.label)return value.label;if(value?.value)return String(value.value);return ""}
function callMatchesTask(call:any,task:WorkflowTask){if(call.task_id)return call.task_id===task.task_id;if(call.created_at&&task.created_at&&task.updated_at){const callTime=Date.parse(call.created_at),started=Date.parse(task.created_at),finished=Date.parse(task.updated_at)+1000;if(Number.isFinite(callTime)&&Number.isFinite(started)&&Number.isFinite(finished)&&(callTime<started||callTime>finished))return false}const role=String(call.role||"").toLowerCase(),stage=String(call.stage||"").toLowerCase(),agent=task.agent.toLowerCase();if(agent==="research_planner")return ["planner","review","research"].some(value=>role.includes(value))||["intent_analysis","study_design","critical_review","synthesis","research_planning","requirement_compilation"].includes(stage);if(agent==="resource_discovery")return role.includes("discovery")||role.includes("query")||stage.includes("query");if(agent.includes("evidence"))return role.includes("evidence")||role.includes("curation")||stage.includes("pairing_verification");if(agent.includes("asset")||agent.includes("inventory"))return role.includes("asset")||role.includes("inventory")||stage.includes("pair_unit");if(agent.includes("acquisition"))return role.includes("acquisition");return role.includes(agent.replaceAll("_",""))}
