    if(option.id==="provide_clarification"&&!clarification){
      setError(language==="zh"?"请先填写需要补充或修正的研究要求。":"Enter the research clarification before submitting.");
      return;
    }
    const resolution:any={option:option.id};
    if(option.id==="provide_clarification")resolution.clarification=clarification;
    const response=await fetch("/checkpoints/"+checkpoint.checkpoint_id+"/resolve",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({resolution})});
    if(!response.ok){const body=await response.json().catch(()=>({}));setError(body.detail||ui(language,"decisionError"));return}
    if(option.id==="provide_clarification")setClarifications(current=>({...current,[checkpoint.checkpoint_id]:""}));
    await onChanged();
    const replies:Record<string,[string,string]>={approve_snapshot:["已批准并锁定本次语料快照。","The corpus snapshot was approved and locked."],reject_snapshot:["已保留为草稿，快照尚未锁定。","The snapshot remains an unlocked draft."],plan_only:["已选择仅保留下载方案，本次不会下载文件。","The download plan was retained without transferring files."],recommended:["已批准下载推荐数据包，流程将开始传输。","Recommended bundles were approved for transfer."],all_with_unknown_size:["已批准下载推荐及符合条件的待复核数据包，并允许文件大小未知。","Recommended and eligible review bundles were approved, including unknown sizes."],provide_clarification:["已记录补充说明，系统将据此重新生成研究方案。","The clarification was recorded and the research plan will be regenerated."],proceed_with_assumptions:["已确认按当前假设继续，相关假设将保留在运行记录中。","The workflow will proceed with its documented assumptions."]},choice=replies[option.id];
    setReply(choice?(language==="zh"?choice[0]:choice[1]):ui(language,"decisionSubmitted"));
