function catalogValue(row:any,column:CatalogColumn,language:Language){const value=row?.[column.key];if(value===null||value===undefined||value==="")return "—";if(column.key==="size_bytes"&&Number.isFinite(Number(value))){const bytes=Number(value),units=["B","KB","MB","GB","TB"];let size=bytes,index=0;while(size>=1024&&index<units.length-1){size/=1024;index++}return size.toFixed(index>1?2:0)+" "+units[index]}if(Array.isArray(value))return value.join(language==="zh"?"、":", ");if(typeof value==="object")return JSON.stringify(value);return localizedValue(value,language)}
function CatalogWorkspace({catalog,runId,language}:{catalog:any|undefined|null;runId:string;language:Language}){const[active,setActive]=useState<CatalogSheetId>("studies"),[query,setQuery]=useState(""),[page,setPage]=useState(0),tableRef=useRef<HTMLDivElement>(null);const sheet=CATALOG_SHEETS.find(item=>item.id===active)!,rows:any[]=catalog?.[active]||[],needle=query.trim().toLocaleLowerCase(),filtered=needle?rows.filter(row=>Object.values(row).some(value=>String(value??"").toLocaleLowerCase().includes(needle))):rows,pageSize=20,pageCount=Math.max(1,Math.ceil(filtered.length/pageSize)),safePage=Math.min(page,pageCount-1),visible=filtered.slice(safePage*pageSize,(safePage+1)*pageSize);useEffect(()=>{tableRef.current?.scrollTo({top:0,left:0,behavior:"auto"})},[active,safePage]);const choose=(id:CatalogSheetId)=>{setActive(id);setQuery("");setPage(0);window.requestAnimationFrame(()=>{tableRef.current?.scrollTo({top:0,left:0,behavior:"auto"});tableRef.current?.scrollIntoView({block:"start",behavior:"smooth"})})};return <div className="catalog-workspace"><div className="catalog-tabs" role="tablist" aria-label={language==="zh"?"候选数据子表":"Candidate dataset sheets"}>{CATALOG_SHEETS.map(item=><button type="button" role="tab" aria-selected={active===item.id} className={active===item.id?"active":""} key={item.id} onClick={()=>choose(item.id)}><b>{item.code}</b><span>{language==="zh"?item.zh:item.en}</span><em>{catalog?.[item.id]?.length||0}</em></button>)}</div><div className="catalog-toolbar"><div><strong>{sheet.code}_{language==="zh"?sheet.zh:sheet.en}</strong><p>{language==="zh"?sheet.descriptionZh:sheet.descriptionEn}</p></div><div className="catalog-actions"><label><span className="sr-only">{language==="zh"?"搜索当前子表":"Search current sheet"}</span><input type="search" value={query} onChange={event=>{setQuery(event.target.value);setPage(0)}} placeholder={language==="zh"?"搜索当前子表…":"Search this sheet…"}/></label><a className="catalog-download" href={"/runs/"+runId+"/curation-catalog.xlsx"}>{language==="zh"?"下载 Excel":"Download XLSX"}</a></div></div>{catalog===undefined?<div className="catalog-message"><span className="catalog-loader"/>{language==="zh"?"正在整理四张子表…":"Preparing the four catalog sheets…"}</div>:catalog===null?<div className="catalog-message error">{language==="zh"?"暂时无法读取四张子表，请稍后刷新。":"The catalog sheets are temporarily unavailable. Please refresh shortly."}</div>:<><div ref={tableRef} className={"catalog-table-wrap sheet-"+active}><table className="catalog-table"><thead><tr>{sheet.columns.map(column=><th className={"group-"+(column.group||"identity")} key={column.key}>{language==="zh"?column.zh:column.en}</th>)}</tr></thead><tbody>{visible.length?visible.map((row,rowIndex)=><tr key={(row.study_accession||row.dataset_id||row.pair_unit_id||"row")+"-"+(safePage*pageSize+rowIndex)}>{sheet.columns.map(column=>{const value=catalogValue(row,column,language),status=/status|priority|queue_action/.test(column.key)||["omics_layer","file_role","record_level","category_family"].includes(column.key),statusKey=String(row[column.key]??"").toLowerCase().replaceAll(/[^a-z0-9]+/g,"-");return <td className={(column.code?" code-cell":"")+(column.numeric?" numeric-cell":"")+(status?" status-cell":"")} key={column.key}>{column.link&&value!=="—"?<a href={String(row[column.key])} target="_blank" rel="noreferrer">{language==="zh"?"打开链接 ↗":"Open ↗"}</a>:status&&value!=="—"?<span className={"catalog-status "+statusKey}>{value}</span>:value}</td>})}</tr>):<tr><td colSpan={sheet.columns.length}><div className="catalog-empty"><b>{language==="zh"?"当前子表暂无记录":"No records in this sheet yet"}</b><span>{language==="zh"?(active==="pair_units"?"流程尚未解析出可追溯的 RNA–ATAC 配对单元。":active==="files"?"流程尚未生成逐文件下载清单。":"没有符合当前筛选条件的记录。"):(active==="pair_units"?"No traceable RNA–ATAC pair units have been resolved yet.":active==="files"?"No file-level download manifest has been produced yet.":"No rows match the current filter.")}</span></div></td></tr>}</tbody></table></div><div className="catalog-footer"><span>{filtered.length?language==="zh"?"显示 "+(safePage*pageSize+1)+"–"+Math.min((safePage+1)*pageSize,filtered.length)+"，共 "+filtered.length+" 条":"Showing "+(safePage*pageSize+1)+"–"+Math.min((safePage+1)*pageSize,filtered.length)+" of "+filtered.length:language==="zh"?"0 条记录":"0 records"}</span><div><button type="button" disabled={safePage===0} onClick={()=>setPage(value=>Math.max(0,value-1))}>{language==="zh"?"上一页":"Previous"}</button><b>{safePage+1} / {pageCount}</b><button type="button" disabled={safePage>=pageCount-1} onClick={()=>setPage(value=>Math.min(pageCount-1,value+1))}>{language==="zh"?"下一页":"Next"}</button></div></div></>}</div>}
function ResultsPanel({artifacts,runId,language}:{artifacts:any[];runId:string;language:Language}){const[catalog,setCatalog]=useState<any|undefined|null>(undefined);const latest=(kind:string)=>artifacts.filter(item=>item.kind===kind).at(-1)?.payload||{};const discovery=latest("discovery_result"),evidence=latest("evidence_review"),preflight=latest("preflight_report"),acquisition=latest("acquisition_plan");const candidates=evidence.candidates||discovery.candidates||[],reports=preflight.reports||[],ready=reports.filter((item:any)=>item.decision==="preflight_ready").length,stats=[[ui(language,"candidates"),catalog?.studies?.length??evidence.candidate_count??candidates.length],[ui(language,"readyBundles"),ready],[ui(language,"recommended"),(acquisition.recommended_bundle_ids||[]).length]];useEffect(()=>{let alive=true;fetch("/runs/"+runId+"/curation-catalog").then(response=>response.ok?response.json():Promise.reject()).then(value=>{if(alive)setCatalog(value)}).catch(()=>{if(alive)setCatalog(null)});return()=>{alive=false}},[runId,artifacts.length]);return <section className="results-panel results-wide"><div className="section-heading"><div><p className="eyebrow">{language==="zh"?"筛选结果":"Downstream result"}</p><h2>{ui(language,"downstreamResult")}</h2></div><Help text={language==="zh"?"四张子表分别记录研究、配对单元、文件清单和待审计问题；所有值均来自本次运行产物。":"The four sheets contain studies, pair units, file manifests, and audit/hold items; every value comes from this run's artifacts."}/></div><div className="results-layout catalog-results-layout"><aside className="result-stats vertical">{stats.map(([label,value])=><div className="result-stat" key={String(label)}><b>{value as any}</b><span>{label}</span></div>)}</aside><CatalogWorkspace catalog={catalog} runId={runId} language={language}/></div></section>}
function modelUsageTotals(calls:any[]){return calls.reduce((totals,call)=>{const usage=call.usage||call.usage_metadata||{},prompt=Number(usage.prompt_tokens||usage.input_tokens||0),completion=Number(usage.completion_tokens||usage.output_tokens||0),total=Number(usage.total_tokens||usage.total_token_count||prompt+completion||0);return{prompt:totals.prompt+prompt,completion:totals.completion+completion,total:totals.total+total}},{prompt:0,completion:0,total:0})}
function modelProviderLabel(value:any){const key=String(value||"unknown").toLowerCase();return key==="stepfun"?"StepFun":key==="openai"?"OpenAI":key==="anthropic"?"Anthropic":key==="langchain"?"LangChain":String(value||"Unknown")}
function ModelUsageCard({calls,language}:{calls:any[];language:Language}){const usage=modelUsageTotals(calls),format=(value:number)=>new Intl.NumberFormat(language==="zh"?"zh-CN":"en-US").format(value),modelNames=Array.from(new Set(calls.map((call:any)=>modelProviderLabel(call.client||call.provider)+" API · "+String(call.model||"—")))),detail=language==="zh"?"Token 由模型供应商返回的输入与输出用量相加；当前显示实际使用的模型 API。":"Tokens are provider-reported input plus output usage for the model APIs used.";return <div className="run-usage" title={detail}><span className="run-label">{language==="zh"?"已使用的模型 API":"MODEL API USED"}</span><div className="run-model-line"><small>{language==="zh"?"供应商与模型":"Provider & model"}</small><b>{modelNames.length?modelNames.join(" / "):"—"}</b></div><div className="run-usage-grid"><span><b>{format(calls.length)}</b><small>{language==="zh"?"调用次数":"API calls"}</small></span><span><b>{format(usage.total)}</b><small>{language==="zh"?"Token 总量":"Total tokens"}</small></span></div><p className="run-token-formula"><span>{language==="zh"?"输入":"Input"} {format(usage.prompt)}</span><i>+</i><span>{language==="zh"?"输出":"Output"} {format(usage.completion)}</span><i>=</i><strong>{format(usage.total)}</strong></p></div>}
const PROCESS_MAP_X:Record<string,number>={asset_scout_direct:185,evidence_metadata:350,evidence_escalation_gate:185,evidence_fulltext:350,asset_scout_enriched:350,geo_sample_metadata:185,inventory_reconcile:268,preflight_assessment:185,early_lineage:350,acquisition_strategy:185,download_approval:350};
function rebalanceProcessMap(topology:any){return topology?{...topology,nodes:(topology.nodes||[]).map((node:any)=>PROCESS_MAP_X[node.id]===undefined?node:{...node,x:PROCESS_MAP_X[node.id]})}:topology}
function normalizeRunPayload(data:any){const activeTask=(data.tasks||[]).some((task:any)=>task.status==="running"),openDecision=(data.checkpoints||[]).some((checkpoint:any)=>checkpoint.status==="open"),staleWaiting=data.run?.status==="waiting_for_decision"&&activeTask&&!openDecision;return {...data,run:staleWaiting?{...data.run,status:"running"}:data.run,workflow_topology:rebalanceProcessMap(data.workflow_topology)}}
function Run(){
  const{runId}=useParams();
  const[d,setD]=useState<any>();
  const[selected,setSelected]=useState<string|null>(null),[language,setLanguage]=useState<Language>(()=>localStorage.getItem("celllore-language")==="zh"?"zh":"en");
  const load=()=>fetch("/runs/"+runId,{cache:"no-store"}).then(response=>response.ok?response.json():Promise.reject(new Error("run"))).then(data=>setD(normalizeRunPayload(data)));
  useEffect(()=>{void load();const timer=window.setInterval(()=>void load(),2500),stream=new EventSource("/runs/"+runId+"/events");["task_started","task_finished","checkpoint_resolved","checkpoint_created","inventory_progress"].forEach(type=>stream.addEventListener(type,load));return()=>{window.clearInterval(timer);stream.close()}},[runId]);
  useEffect(()=>{localStorage.setItem("celllore-language",language);document.documentElement.lang=language==="zh"?"zh-CN":"en"},[language]);
  if(!d)return <Shell language={language} onLanguageChange={()=>setLanguage(current=>current==="en"?"zh":"en")}><p>{language==="zh"?"加载中…":"Loading…"}</p></Shell>;
  return <Shell language={language} onLanguageChange={()=>setLanguage(current=>current==="en"?"zh":"en")}><section className="run-page"><Link className="back-link" to="/#workspace">← {ui(language,"allRuns")}</Link><div className="run-hero"><div><span className={"pill "+d.run.status}>{statusText(d.run.status,language)}</span><h1>{d.run.question}</h1></div><div className="run-summary-cards"><div className="run-meta"><span className="run-label">{ui(language,"run")}</span><code>{d.run.run_id}</code><span className="run-duration"><small>{language==="zh"?"总耗时":"Total duration"}</small><b>{formatDuration(((["queued","running"].includes(d.run.status))?Date.now():Date.parse(d.run.updated_at))-Date.parse(d.run.created_at))}</b></span></div><ModelUsageCard calls={d.llm_calls||[]} language={language}/></div></div><div className="console-grid"><section className="left-console"><div className="card topology-card"><div className="section-heading"><div><p className="eyebrow">{language==="zh"?"流程图":"Process map"}</p><h2>{ui(language,"processMap")}</h2></div></div><AgentActivityDock tasks={d.tasks} artifacts={d.artifacts} topology={d.workflow_topology} inventoryProgress={d.inventory_progress} runStatus={d.run.status} language={language}/><WorkflowGraph tasks={d.tasks} topology={d.workflow_topology} selected={selected} language={language} onSelect={task=>setSelected(current=>current===task.task_id?null:task.task_id)}/>{d.workflow_topology?.trace_complete===false?<p className="topology-trace-note">{ui(language,"partialTrace")}</p>:null}</div></section><aside className="right-console"><OutputPanel tasks={d.tasks} artifacts={d.artifacts} messages={d.messages||[]} llmCalls={d.llm_calls||[]} selected={selected} language={language} topology={d.workflow_topology} inventoryProgress={d.inventory_progress}/></aside></div><HumanLoopPanel checkpoints={d.checkpoints} runId={d.run.run_id} onChanged={load} language={language}/><ResultsPanel artifacts={d.artifacts} runId={d.run.run_id} language={language}/></section></Shell>
}
export function App(){return <Routes><Route path="/" element={<Home/>}/><Route path="/ui/runs/:runId" element={<Run/>}/><Route path="*" element={<Home/>}/></Routes>}
